mapper.select:
select t.attr_id,t.attr_id attrId,t.machine_id,t.machine_id machineId,t.spec_cd,t.spec_cd
specCd,t.community_id,t.community_id communityId,t.value
from monitor_machine_attrs t
where 1 =1

    and t.attr_id= #{attrId}


    and t.machine_id= #{machineId}


    and t.spec_cd= #{specCd}


    and t.community_id= #{communityId}


    and t.value= #{value}


    and t.status_cd= #{statusCd}

order by t.create_time desc

    limit #{page}, #{row}

